<summary>Bench adapter and configs</summary>

```ts
// apps/testbed/e2e.bench-decision.config.ts (local only)
const flat = (value: unknown): string => (typeof value === 'string' ? value : JSON.stringify(value));
const jev = {
  specificationVersion: 'v4' as const,
  provider: 'typesafe',
  modelId: 'typesafe/jev-1.13',
  supportedQuestionTypes: ['choice' as const],
  async doEvaluate({ state, questions, abortSignal }) {
    const flatQuestions = Object.fromEntries(Object.entries(questions).map(([id, q]) => [id, {
      type: q.type,
      instructions: flat(q.instructions),
      criteria: Object.fromEntries(Object.entries(q.criteria).map(([k, v]) => [k, flat(v ?? '')])),
    }]));
    const response = await fetch('https://api-gateway.merge.dev/v1/decisions', {
      method: 'POST',
      headers: { Authorization: `Bearer ${process.env.MERGE_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'typesafe/jev-1.13', state, questions: flatQuestions }),
      signal: abortSignal,
    });
    if (!response.ok) throw new Error(`decision gateway HTTP ${response.status}`);
    const body = await response.json();
    const answers = {};
    const confidence = {};
    for (const [id, a] of Object.entries(body.answers)) {
      answers[id] = { type: 'choice', choice: a.choice, probabilities: a.probabilities };
      confidence[id] = a.confidence;
    }
    return {
      answers,
      rounding: { probabilityDecimals: 2 },
      usage: { inputTokens: body.usage.input_tokens, outputTokens: body.usage.output_tokens },
      warnings: [],
      providerMetadata: { typesafe: { confidence } },
      response: { modelId: body.model },
    };
  },
};
// agents.default: { executor: decisionExecutor({ model: jev, textModel: opencodex('gpt-6-luna') }), context }
// baseline:       { model: opencodex('gpt-6-luna'), maxSteps: 40, maxModelCalls: 60, context }
