import { writeFileSync } from 'node:fs';
import type { E2EConfig, StepExecutor } from 'e2e';
import { defineEngine, ENGINE_SPI_VERSION, resolveExpression, type SemanticNode } from 'e2e/engine';

const label = process.env.REPRO_LABEL ?? 'Example record';
let present = true;
let clock = process.env.CLOCK_BEFORE ?? '10:00';
const node = (id: string, fields: Omit<SemanticNode, 'ref'>): SemanticNode => ({
  ref: { id, revision: '' }, ...fields,
});
const tree = (): SemanticNode => node('root', { role: 'document', children: [
  node('clock', { text: clock }),
  ...(present ? [node('row', { role: 'row', name: label, children: [node('delete', { role: 'button', name: 'Delete' })] })] : []),
] });

const engine = defineEngine({
  name: 'memory-repro', version: '1', spiVersion: ENGINE_SPI_VERSION,
  async init() {},
  async startAttempt() { present = true; clock = process.env.CLOCK_BEFORE ?? '10:00'; },
  async endAttempt() {},
  async dispose() {},
  session: { async open() {} },
  actions: ['tap'],
  async observe() { return { root: tree(), location: 'http://127.0.0.1:4599/', viewport: { width: 800, height: 600 } }; },
  async locate(expression) { return resolveExpression(expression, tree().children ?? []); },
  async perform(ref, action) {
    if (ref.id !== 'delete' || action.kind !== 'tap' || !present) throw new Error('Unexpected action');
    present = false;
    clock = process.env.CLOCK_AFTER ?? clock;
  },
});

const executor: StepExecutor = {
  name: 'repro-executor', version: '1',
  async runStep(context) {
    if (context.step.instruction.startsWith('Capture')) {
      writeFileSync('ledger.json', JSON.stringify({ currentLabel: context.step.params?.label, ledger: context.ledger }, null, 2));
      return { status: 'passed', summary: 'Captured the executor input without judging it.' };
    }
    const observed = await context.observe();
    const id = /^\s*#(\S+) button "Delete"/m.exec(observed.text)?.[1];
    if (!id) return { status: 'failed', summary: 'Delete button missing.' };
    await context.actions.tap({ id });
    return { status: 'passed', summary: `Deleted ${context.step.params?.label ?? label}.` };
  },
};

export default {
  tests: ['tests/*.e2e.ts'],
  targets: [{ name: 'memory', platform: 'web', engine, app: { url: 'http://127.0.0.1:4599/' } }],
  agents: { default: { executor } },
  cache: { mode: 'read-write', dir: '.e2e/cache' },
  workers: 1, retries: 0, timeout: 30_000,
} satisfies E2EConfig;
