  response.writeHead(200, { "content-type": "text/plain" });
  response.end("ok");
});
server.listen(Number(process.env.PORT), "127.0.0.1");
setTimeout(() => {
  console.log("server exiting on purpose");
  process.exit(1);
}, 3000);
```

